import csv
import io
import re
from typing import List, Tuple


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = []
    try:
        for record in reader:
            if record and any(value != "" for value in record):
                records.append(record)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    number_pattern = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")

    def header_score(record):
        return sum(
            1 for value in record
            if value.strip() and not number_pattern.fullmatch(value.strip())
        )

    expected_width = 9
    candidates = [
        index for index, record in enumerate(records)
        if len(record) == expected_width and header_score(record) > 0
    ]
    if candidates:
        header_index = max(candidates, key=lambda index: (header_score(records[index]), -index))
    else:
        header_index = 0

    columns = list(records[header_index])
    width = max(len(columns), expected_width, max(len(record) for record in records))
    columns.extend("Column_{}".format(index + 1) for index in range(len(columns), width))
    columns = [
        value if value else "Column_{}".format(index + 1)
        for index, value in enumerate(columns)
    ]

    rows = []
    for index, record in enumerate(records):
        if index == header_index:
            continue
        rows.append(record[:width] + [""] * max(0, width - len(record)))

    return {"columns": columns, "rows": rows}
